<div class="website-section website-fields"><label>Section title<input name="sections[{{ $i }}][title]" value="{{ $section['title'] ?? '' }}" required></label><label>Text<textarea name="sections[{{ $i }}][body]" rows="3">{{ $section['body'] ?? '' }}</textarea></label><label>Button text<input name="sections[{{ $i }}][link_label]" value="{{ $section['link_label'] ?? '' }}"></label><label>Button destination<input name="sections[{{ $i }}][link_url]" value="{{ $section['link_url'] ?? '' }}" placeholder="/galleries or https://..."></label><label>Section type<select name="sections[{{ $i }}][kind]"><option value="content" @selected(($section['kind'] ?? 'content')==='content')>Page content</option><option value="crew_placeholder" @selected(($section['kind'] ?? '')==='crew_placeholder')>Placeholder crew bio (About page)</option></select></label><input type="hidden" name="sections[{{ $i }}][visible]" value="0"><label class="website-check"><input type="checkbox" name="sections[{{ $i }}][visible]" value="1" @checked($section['visible'] ?? true)>Show section</label><div class="website-actions"><button type="button" class="button secondary" data-move-up>Move up</button><button type="button" class="button secondary" data-move-down>Move down</button><button type="button" class="button secondary" data-remove-section>Remove section</button></div></div>
